package com.frs.backend.service.impl;

import jakarta.annotation.PostConstruct;import nu.pattern.OpenCV;import org.opencv.core.*;import org.opencv.imgproc.Imgproc;import org.opencv.objdetect.CascadeClassifier;import org.springframework.stereotype.Service;import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import java.io.*;import java.util.*;
@Service public class FaceDescriptorServiceImpl implements com.frs.backend.service.FaceDescriptorService {
 private CascadeClassifier detector; private volatile boolean loaded=false;
 @PostConstruct public void load(){try{OpenCV.loadLocally();try(InputStream in=getClass().getResourceAsStream("/models/haarcascade_frontalface_default.xml")){if(in==null)throw new IOException("Missing Haar cascade");File file=File.createTempFile("frs-face-",".xml");file.deleteOnExit();java.nio.file.Files.copy(in,file.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);detector=new CascadeClassifier(file.getAbsolutePath());loaded=!detector.empty();}}catch(Throwable e){System.err.println("Face detector initialization failed: "+e.getMessage());loaded=false;}}
 public boolean loaded(){return loaded;}
 public double[] descriptor(String input) throws Exception {
  if(input==null||input.isBlank())throw new IllegalArgumentException("Face image is required");String b64=input.replaceFirst("^data:image/[A-Za-z0-9.+-]+;base64,","");byte[] bytes;try{bytes=Base64.getDecoder().decode(b64);}catch(Exception e){throw new IllegalArgumentException("Invalid image data");}if(bytes.length==0)throw new IllegalArgumentException("Invalid image data");BufferedImage image=ImageIO.read(new ByteArrayInputStream(bytes));if(image==null)throw new IllegalArgumentException("Invalid image data");
  int w=image.getWidth(),h=image.getHeight();byte[] pixels=new byte[w*h*3];int k=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int rgb=image.getRGB(x,y);pixels[k++]=(byte)((rgb>>16)&255);pixels[k++]=(byte)((rgb>>8)&255);pixels[k++]=(byte)(rgb&255);}Mat color=new Mat(h,w,CvType.CV_8UC3);color.put(0,0,pixels);Mat gray=new Mat();Imgproc.cvtColor(color,gray,Imgproc.COLOR_RGB2GRAY);MatOfRect faces=new MatOfRect();detector.detectMultiScale(gray,faces,1.1,4,0,new Size(30,30),new Size());Rect[] found=faces.toArray();if(found.length==0)throw new IllegalArgumentException("No face detected. Please capture a clear face image.");Rect face=Arrays.stream(found).max(Comparator.comparingLong(r->(long)r.width*r.height)).orElse(found[0]);Mat crop=new Mat(gray,face),small=new Mat();Imgproc.resize(crop,small,new Size(16,8));double[] result=new double[128];double mean=0;for(int y=0;y<8;y++)for(int x=0;x<16;x++){double[] v=small.get(y,x);result[y*16+x]=v[0]/255.0;mean+=result[y*16+x];}mean/=128;double norm=0;for(int i=0;i<128;i++){result[i]-=mean;norm+=result[i]*result[i];}norm=Math.sqrt(norm);if(norm>1e-12)for(int i=0;i<128;i++)result[i]/=norm;return result;
 }
}
